import * as React from "react";

export type CassetteIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CassetteIcon({ size = 20, ...props }: CassetteIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="3.5" y="6" width="17" height="12" rx="1.5" /><circle cx="9" cy="12" r="1.8" /><circle cx="15" cy="12" r="1.8" /><path d="M6 18l1.5-3M18 18l-1.5-3" />
    </svg>
  );
}
